from orders.db import get_conn


def get_order(order_id):
    conn = get_conn()
    try:
        rows = conn.execute("SELECT id, customer_id, total_cents, status FROM orders WHERE id = :id", {"id": order_id})
    finally:
        conn.close()
    if not rows:
        return None
    row = rows[0]
    return {"id": row["id"], "customer_id": row["customer_id"], "total_cents": row["total_cents"], "status": row["status"]}


def list_orders_for_customer(customer_id):
    conn = get_conn()
    try:
        rows = conn.execute("SELECT id, total_cents, status FROM orders WHERE customer_id = :customer_id ORDER BY id", {"customer_id": customer_id})
    finally:
        conn.close()
    return [{"id": row["id"], "total_cents": row["total_cents"], "status": row["status"]} for row in rows]


def create_order(customer_id, total_cents):
    conn = get_conn()
    try:
        row = conn.execute(
            "INSERT INTO orders (customer_id, total_cents, status) VALUES (:customer_id, :total_cents, 'new') RETURNING id",
            {"customer_id": customer_id, "total_cents": total_cents},
        )
        new_id = row[0]["id"]
    finally:
        conn.close()
    return new_id

